window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[311]={"id":"311","numero":311,"titre":"Tumeurs du rein de l'adulte","objectifs":[{"id":"311-1","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie des tumeurs du rein","contenu":"<p>Le <span class=\"kw-def\">cancer du rein</span> est la <span class=\"kw-etio\">6ᵉ tumeur solide maligne</span> en France et le <span class=\"kw-etio\">3ᵉ cancer urologique</span> (après <span class=\"kw-def\">prostate</span> et <span class=\"kw-def\">vessie</span>). Son <span class=\"kw-def\">incidence</span> est <span class=\"kw-alerte\">croissante chez l'homme comme chez la femme</span>, sous l'effet conjoint de la <span class=\"kw-etio\">découverte fortuite des petites tumeurs</span> (imagerie pour autre motif), de l'<span class=\"kw-etio\">augmentation des facteurs de risque environnementaux</span> et du <span class=\"kw-etio\">vieillissement de la population</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Indicateur</th><th>Valeur (France, 2018)</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Nouveaux cas / an</td><td><span class=\"kw-chiffre\">15 323</span></td></tr>\n          <tr><td>Décès / an</td><td><span class=\"kw-chiffre\">5 589</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Évolution</span> de l'<span class=\"kw-def\">incidence</span> (1990-2018)</td><td><strong>Homme :</strong> <span class=\"kw-chiffre\">+ 1,7 %</span>/an ; <br><strong>Femme :</strong> <span class=\"kw-chiffre\">+ 1,4 %</span>/an</td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span> (taux pour 100 000)</td><td><strong>Homme :</strong> <span class=\"kw-chiffre\">5</span> ; <br><strong>Femme :</strong> <span class=\"kw-chiffre\">1,5</span></td></tr>\n          <tr><td>Pic d'<span class=\"kw-def\">incidence</span> (âge)</td><td><span class=\"kw-chiffre\">60-70 ans</span></td></tr>\n          <tr><td>Âge médian au décès</td><td><span class=\"kw-chiffre\">75-80 ans</span></td></tr>\n          <tr><td>Sex-ratio (H / F)</td><td><span class=\"kw-chiffre\">1,5 / 1</span></td></tr>\n          <tr><td>Survie nette à<span class=\"kw-chiffre\"> 5 ans</span></td><td><span class=\"kw-chiffre\">70 %</span></td></tr>\n          <tr><td>Survie nette à<span class=\"kw-chiffre\"> 10 ans</span></td><td><span class=\"kw-chiffre\">&gt; 50 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 <strong>À retenir.</strong> La <span class=\"kw-clinique\">découverte fortuite</span> représente <span class=\"kw-chiffre\">70-80 %</span> des diagnostics (incidentalome sur imagerie demandée pour un autre motif). La majorité des tumeurs du rein sont <span class=\"kw-alerte\">malignes</span>, mais un certain nombre sont <span class=\"kw-def\">bénignes</span> ou ont un faible potentiel évolutif — d'où l'importance de la démarche diagnostique paraclinique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — <span class=\"kw-def\">Épidémiologie</span> des cancers · 310 — Tumeurs de la prostate · 313 — Tumeurs du testicule · 314 — Tumeurs de la vessie</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/renal-tumours-1","label":"Radiopaedia : Renal tumours 1"},{"href":"https://radiopaedia.org/articles/renal-angiomyolipoma","label":"Angiomyolipome"},{"href":"https://radiopaedia.org/articles/international-society-of-urological-pathology-vancouver-classification-of-renal-neoplasia-historical","label":"Radiopaedia : International society of urological pathology vancouver classification of renal neoplasia historical"},{"href":"https://radiopaedia.org/articles/renal-cyst-1","label":"Radiopaedia : Renal cyst 1"},{"href":"https://radiopaedia.org/articles/clear-cell-renal-cell-carcinoma","label":"Radiopaedia : Clear cell renal cell carcinoma"},{"href":"https://radiologyassistant.nl/abdomen/kidney/bozniak-2019","label":"Bozniak 2019"},{"href":"https://radiopaedia.org/articles/bosniak-classification-system-of-renal-cystic-masses-version-2005-1","label":"Radiopaedia : Bosniak classification system of renal cystic masses version 2005 1"}]},{"id":"311-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">facteurs de risque</span> de cancer du rein se répartissent entre <span class=\"kw-def\">FdR acquis</span> (<span class=\"kw-def\">terrain</span>, mode de vie, expositions professionnelles) et <span class=\"kw-def\">prédispositions génétiques familiales</span> (<span class=\"kw-chiffre\">~ 5 %</span> des cas, à transmission <span class=\"kw-alerte\">autosomique dominante</span>).</p>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs de risque</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Terrain</span> / mode de vie</td><td><strong>Cardiovasculaire :</strong> <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">obésité</span>, <span class=\"kw-etio\">HTA</span> ; <br><strong>Rénal :</strong> <span class=\"kw-etio\">insuffisance rénale chronique</span>, <span class=\"kw-etio\">transplantation rénale</span>, <span class=\"kw-etio\">hémodialyse au long cours</span></td></tr>\n          <tr><td>Expositions environnementales et professionnelles</td><td><strong>Solvant :</strong> <span class=\"kw-etio\">trichloréthylène</span> ; <br><strong>FdR professionnels :</strong> <span class=\"kw-etio\">amiante</span>, <span class=\"kw-etio\">cadmium</span></td></tr>\n          <tr><td>Prédispositions génétiques (~<span class=\"kw-chiffre\"> 5 %</span>)</td><td><strong>Voir tableau des syndromes héréditaires ci-dessous</strong> (5 entités à connaître)</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Syndromes héréditaires associés aux tumeurs du rein</h4>\n      <table >\n        <thead>\n          <tr><th>Affection (gène)</th><th>Tumeurs rénales</th><th>Manifestations extra-rénales</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Maladie de Von Hippel-Lindau</span> (<em>VHL</em>)</td>\n            <td><span class=\"kw-imagerie\">Carcinomes à cellules claires</span> ; <br><span class=\"kw-imagerie\">Kystes rénaux</span></td>\n            <td><strong>SNC / rétine :</strong> hémangioblastomes ; <br><strong>Pancréas :</strong> kystes, tumeurs endocrines ; <br><strong>Surrénale :</strong> phéochromocytomes ; <br><strong>ORL :</strong> tumeurs du sac endolymphatique ; <br><strong>Génital :</strong> cystadénomes de l'épididyme</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Cancer rénal papillaire héréditaire</span> (<em>MET</em>)</td>\n            <td><span class=\"kw-imagerie\">Carcinomes papillaires de type 1</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Léiomyomatose cutanéo-utérine héréditaire</span> (<em>FH</em>)</td>\n            <td><span class=\"kw-imagerie\">Carcinomes papillaires de type 2</span> (principal) ; <br><span class=\"kw-imagerie\">Carcinomes des tubes collecteurs</span></td>\n            <td><strong>Peau :</strong> léiomyomes cutanés ; <br><strong>Utérus :</strong> léiomyomes utérins</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Syndrome de Birt-Hogg-Dubé</span> (<em>FLCN / BHD</em>)</td>\n            <td><span class=\"kw-imagerie\">Carcinomes chromophobes</span> ; <br>Tumeurs hybrides ; <br>Oncocytomes ; <br>Carcinomes à cellules claires</td>\n            <td><strong>Peau :</strong> fibrofolliculomes ; <br><strong>Poumon :</strong> pneumothorax spontanés, kystes pulmonaires</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Sclérose tubéreuse de Bourneville</span> (<em>TSC1 / TSC2</em>)</td>\n            <td><span class=\"kw-imagerie\">Angiomyolipomes</span> fréquents ; <br>Kystes rénaux ; <br>Angiomyolipomes épithélioïdes ; <br><span class=\"kw-clinique\">Carcinome</span> à cellules claires</td>\n            <td><strong>SNC :</strong> épilepsie, retard mental, nodules sous-épendymaires, astrocytome à cellules géantes ; <br><strong>Peau :</strong> angiofibromes faciaux, tumeurs de Koenen, taches achromiques, plaques en peau de chagrin ; <br><strong>Cœur :</strong> rhabdomyome ; <br><strong>Poumon :</strong> lymphangioléiomyomatose ; <br><strong>Œil :</strong> hamartomes rétiniens</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">🧬 <strong>Indications de consultation oncogénétique</strong> (à proposer si <span class=\"kw-chiffre\">≥ 1</span> critère) : <br>• <span class=\"kw-chiffre\">Âge &lt; 45 ans</span> au diagnostic ; <br>• Sous-type histologique <span class=\"kw-alerte\">autre que CRCC</span> ; <br>• <span class=\"kw-alerte\">Tumeurs multiples et/ou bilatérales</span> ; <br>• Manifestations extra-rénales évocatrices ; <br>• Plusieurs cas dans la famille.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":1},{"id":"311-3","rang":"B","rubrique":"Définition","titre":"Connaître les principaux types histologiques des tumeurs","contenu":"<p><span class=\"kw-clinique\">Les</span> tumeurs du rein de l'adulte se répartissent en <span class=\"kw-def\">tumeurs malignes</span> (<span class=\"kw-chiffre\">70-80 %</span>) et <span class=\"kw-def\">tumeurs bénignes</span>. Les tumeurs malignes doivent être décrites selon la <span class=\"kw-def\">classification TNM</span> et leur agressivité évaluée par le <span class=\"kw-def\">grade ISUP</span> (International Society of Uro-Pathology, anciennement <span class=\"kw-def\">grade</span> de Fuhrman) sur la <span class=\"kw-imagerie\">biopsie</span> ou la pièce opératoire — <strong>ISUP 1-2 = bas grade, ISUP 3-4 = haut grade</strong>.</p>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th><span class=\"kw-bio\">Histologie</span></th><th>Fréquence</th><th>Caractéristiques clés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td rowspan=\"3\"><span class=\"kw-alerte\">Malignes</span> (<span class=\"kw-chiffre\">70-80 %</span>)</td>\n            <td><span class=\"kw-def\">CRCC</span> (<span class=\"kw-clinique\">carcinome</span> rénal à cellules claires)</td>\n            <td><span class=\"kw-chiffre\">75-85 %</span></td>\n            <td><span class=\"kw-imagerie\">Hypervasculaire</span> ; <br>Voie <span class=\"kw-def\">VHL → HIF → VEGF</span> ; <br>Origine tubule proximal</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">CRTP</span> (<span class=\"kw-clinique\">carcinome</span> tubulo-papillaire) types 1 et 2</td>\n            <td><span class=\"kw-chiffre\">12-14 %</span></td>\n            <td>Type 1 : sporadique ou <span class=\"kw-etio\">héréditaire</span> <em>(MET)</em> ; <br>Type 2 : souvent héréditaire <em>(FH)</em>, plus agressif</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Carcinome chromophobe</span></td>\n            <td><span class=\"kw-chiffre\">4-6 %</span></td>\n            <td>Meilleur <span class=\"kw-def\">pronostic</span> ; <br>Lié au <span class=\"kw-def\">Birt-Hogg-Dubé</span></td>\n          </tr>\n          <tr>\n            <td rowspan=\"2\"><span class=\"kw-def\">Bénignes</span></td>\n            <td><span class=\"kw-def\">Oncocytome</span> (adénome oncocytaire)</td>\n            <td>—</td>\n            <td>Prédominance <span class=\"kw-clinique\">féminine</span> ; <br><span class=\"kw-imagerie\">Cicatrice stellaire centrale</span> parfois visible à l'imagerie</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Angiomyolipome</span> (AML)</td>\n            <td><span class=\"kw-chiffre\">0,1-0,2 %</span> pop. générale</td>\n            <td><strong>Composantes :</strong> vasculaire, musculaire, <span class=\"kw-imagerie\">adipeuse</span> ; <br><strong>Imagerie :</strong> <span class=\"kw-imagerie\">hypodense en TDM</span>, <span class=\"kw-imagerie\">hyperéchogène en échographie</span> ; <br><strong><span class=\"kw-def\">Terrain</span> :</strong> prédominance féminine, peut s'intégrer dans la <span class=\"kw-def\">sclérose tubéreuse de Bourneville</span> (volumineux + multiples) ; <br><strong>CAT :</strong> <span class=\"kw-alerte\">embolisation préventive si taille &gt; 4 cm</span> (risque <span class=\"kw-etio\">hémorragique</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Carcinogénèse du CRCC (à connaître)</h4>\n      <p>Le CRCC se développe à partir des <span class=\"kw-def\">cellules du tubule proximal du néphron</span> par activation des <strong>voies de l'hypoxie</strong> : <span class=\"kw-alerte\">inactivation du gène VHL</span> → expression de la protéine <span class=\"kw-def\">HIF</span> (<em>Hypoxia-Inducible Factor</em>) → surexpression de gènes pro-angiogéniques (notamment <span class=\"kw-def\">VEGF</span>). Conséquences cliniques :</p>\n      <ul>\n        <li>Tumeurs <span class=\"kw-imagerie\">hypervasculaires</span> mais à <span class=\"kw-alerte\">hypervascularisation anarchique</span> — <span class=\"kw-alerte\">risque hémorragique</span> lors de la <span class=\"kw-ttt\">chirurgie</span> sur tumeur primitive ou métastases (justifie parfois une <span class=\"kw-def\">embolisation pré-opératoire</span>) ;</li>\n        <li><span class=\"kw-clinique\">Les</span> <span class=\"kw-clinique\">métastases cérébrales</span> de CRCC peuvent faire des <span class=\"kw-alerte\">hémorragies parenchymateuses</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Histoire naturelle</h4>\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Tropisme vasculaire</strong></td>\n            <td><span class=\"kw-alerte\">Thrombus tumoral</span> dans la <span class=\"kw-clinique\">veine rénale</span>, puis la <span class=\"kw-clinique\">VCI</span>, jusqu'à un <span class=\"kw-bio\">envahissement</span> de l'<span class=\"kw-clinique\">oreillette droite</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Relais ganglionnaires</strong></td>\n            <td><span class=\"kw-clinique\">Hile rénal</span>, puis <span class=\"kw-clinique\">rétropéritoine</span> (lombo-aortiques).</td>\n          </tr>\n          <tr>\n            <td><strong>Métastases (fréquence)</strong></td>\n            <td><span class=\"kw-chiffre\">10-20 %</span> au diagnostic ; <span class=\"kw-chiffre\">10-30 %</span> apparaîtront après néphrectomie pour <span class=\"kw-def\">stade</span> localisé.</td>\n          </tr>\n          <tr>\n            <td><strong>Sites métastatiques principaux</strong></td>\n            <td><span class=\"kw-clinique\">Poumon</span>, <span class=\"kw-clinique\">foie</span>, <span class=\"kw-clinique\">os</span>, <span class=\"kw-clinique\">surrénales</span>, <span class=\"kw-clinique\">cerveau</span>. À souligner : <span class=\"kw-clinique\">métastases glandulaires</span> (<span class=\"kw-clinique\">surrénales</span>, <span class=\"kw-clinique\">pancréas</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">🚩 <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Le cancer du rein peut <span class=\"kw-alerte\">métastaser dans n'importe quel organe</span>, et même <span class=\"kw-alerte\">plusieurs années après le diagnostic</span> initial — toute symptomatologie atypique chez un patient aux ATCD de cancer du rein doit faire évoquer une métastase tardive.</div>","frequence":2},{"id":"311-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les présentations cliniques des tumeurs du rein","contenu":"<p>La présentation clinique des tumeurs du rein est <strong>polymorphe</strong> : la <span class=\"kw-clinique\">découverte fortuite</span> domine très largement (<span class=\"kw-chiffre\">70-80 %</span>), tandis que <span class=\"kw-clinique\">les</span> présentations symptomatiques (triade de Guyon, syndromes paranéoplasiques) traduisent une <span class=\"kw-alerte\">maladie déjà localement avancée ou métastatique</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Mode de révélation</th><th>Caractéristiques cliniques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Découverte fortuite</span> (<span class=\"kw-chiffre\">70-80 %</span>)</td>\n            <td><span class=\"kw-imagerie\">Tumeur incidentale</span> sur imagerie réalisée pour un autre motif (douleur abdominale, <span class=\"kw-def\">bilan d'extension</span>, traumatisme). <br><span class=\"kw-def\">Stade</span> asymptomatique — meilleur <span class=\"kw-def\">pronostic</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Triade classique de Guyon</span> (<span class=\"kw-chiffre\">&lt; 10 %</span>)</td>\n            <td><strong>Trois signes associés :</strong> <span class=\"kw-clinique\">hématurie</span> + <span class=\"kw-clinique\">lombalgie</span> + <span class=\"kw-clinique\">masse lombaire</span>. <br><span class=\"kw-alerte\">Signe une maladie localement avancée</span> — ce n'est <strong>pas</strong> un signe précoce.</td>\n          </tr>\n          <tr>\n            <td>Manifestations locales</td>\n            <td><strong><span class=\"kw-bio\">Hématurie</span> :</strong> microscopique ou <span class=\"kw-clinique\">macroscopique totale</span> ; <br><strong>Colique néphrétique :</strong> par caillotage ou compression si tumeur proche du hile ; <br><strong>Douleur lombaire / <span class=\"kw-clinique\">pesanteur</span> :</strong> si tumeur volumineuse ; <br><strong><span class=\"kw-clinique\">Masse</span> lombaire palpable :</strong> si tumeur volumineuse.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Varicocèle</span> (signe d'extension veineuse)</td>\n            <td><strong>Gauche</strong> (le plus souvent) : par <span class=\"kw-alerte\">thrombus de la veine rénale gauche</span> (anatomie — la veine spermatique G se draine dans la veine rénale G) ; <br><strong>Droit</strong> (plus rare) : par <span class=\"kw-etio\">thrombus</span> de la <span class=\"kw-clinique\">VCI</span>.</td>\n          </tr>\n          <tr>\n            <td>Métastases révélatrices</td>\n            <td><strong>Pulmonaire :</strong> <span class=\"kw-clinique\">dyspnée</span> ; <br><strong>Osseuse :</strong> douleurs, fractures pathologiques ; <br><strong>Cérébrale :</strong> troubles neurologiques focaux, comitialité.</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Syndromes paranéoplasiques (à connaître ++)</h4>\n      <table >\n        <thead>\n          <tr><th>Syndrome</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Polyglobulie</span></td><td>Hypersécrétion d'<span class=\"kw-def\">EPO</span> par la tumeur</td></tr>\n          <tr><td><span class=\"kw-bio\">Anémie</span></td><td>Inflammation chronique / saignement chronique</td></tr>\n          <tr><td><span class=\"kw-bio\">Hypercalcémie</span></td><td>Hypersécrétion de <span class=\"kw-def\">PTHrp</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">HTA</span></td><td>Hypersécrétion de <span class=\"kw-def\">rénine</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">AEG</span></td><td><span class=\"kw-clinique\">Asthénie</span>, fièvre, sueurs nocturnes, <span class=\"kw-clinique\">amaigrissement</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Syndrome inflammatoire biologique</span></td><td>Sd <span class=\"kw-etio\">inflammatoire</span> isolé, parfois inaugural</td></tr>\n          <tr><td><span class=\"kw-alerte\">Syndrome de Stauffer</span> (rare, classique en QCM)</td><td><span class=\"kw-clinique\">Hépatomégalie douloureuse</span> + <span class=\"kw-bio\">anomalies biologiques hépatiques</span>, <span class=\"kw-alerte\">SANS métastase hépatique</span> — piège classique : ne pas conclure à une métastase devant ces anomalies.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>Piège classique sémiologique.</strong> Bien <span class=\"kw-alerte\">distinguer ébranlement lombaire</span> (positif dans <span class=\"kw-clinique\">colique néphrétique</span>, <span class=\"kw-clinique\">PNA</span>) et <span class=\"kw-alerte\">contact lombaire</span> (positif dans <span class=\"kw-clinique\">PKRAD</span>, <span class=\"kw-clinique\">tumeur rénale</span>, <span class=\"kw-clinique\">gros rein</span>) — deux sémiologies palpatoires différentes, l'erreur est fréquente en QCM.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 260 — <span class=\"kw-bio\">Hématurie</span> · 266 — Polykystose rénale · 314 — Tumeurs de la vessie</em></p>","frequence":2},{"id":"311-5","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens complémentaires nécessaires en cas suspicion clinique de tumeur du rein","contenu":"<p>C'est l'objectif <span class=\"kw-alerte\">le plus tombé en QCM EDN</span> sur l'item 311 (<span class=\"kw-chiffre\">8 ⭐</span> brut dans la fiche source). La démarche associe un <span class=\"kw-bio\">bilan biologique standard</span>, une <span class=\"kw-imagerie\">imagerie hiérarchisée</span> (écho → <span class=\"kw-imagerie\">TDM</span>-AP injectée 4 temps + <span class=\"kw-imagerie\">TDM</span> thoracique → <span class=\"kw-imagerie\">IRM</span> si besoin → bilan métastatique si point d'appel), et une <span class=\"kw-def\">biopsie percutanée</span> <strong>non systématique</strong>, indiquée uniquement si elle peut modifier la décision thérapeutique.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Biologie</h4>\n      <table >\n        <thead><tr><th>Contexte</th><th>Bilan</th></tr></thead>\n        <tbody>\n          <tr><td>Tumeur localisée</td><td><span class=\"kw-bio\">NFS</span> ; <br><span class=\"kw-bio\">Créatininémie</span> (calcul du <span class=\"kw-bio\">DFG</span>, indispensable avant <span class=\"kw-imagerie\">TDM</span> injecté)</td></tr>\n          <tr><td>Tumeur métastatique</td><td><strong>En <span class=\"kw-bio\">complément</span> :</strong> <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">bilan d'hémostase</span>, <span class=\"kw-bio\">protidémie</span>, <span class=\"kw-bio\">albuminémie</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Imagerie hiérarchisée — examens à connaître</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Place dans la démarche</th><th>Apport</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Échographie rénale</span></td>\n            <td>1ʳᵉ intention (mode de découverte le plus fréquent)</td>\n            <td><strong>Permet :</strong> <span class=\"kw-imagerie\">différence tumeur solide vs kystique</span> ; <br><strong>Couplable :</strong> injection de PDC (écho de contraste) pour kystes ambigus ; <br><strong>Limite :</strong> <span class=\"kw-alerte\">insuffisante seule pour décider du traitement</span> — toujours complétée par <span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TDM abdominale et pelvienne injectée 4 temps</span> — <span class=\"kw-alerte\">examen de référence</span></td>\n            <td>2ᵉ intention systématique (diagnostic + extension)</td>\n            <td><strong>4 temps obl<span class=\"kw-chiffre\">iga</span>toires :</strong> <span class=\"kw-imagerie\">sans injection</span>, <span class=\"kw-imagerie\">artériel précoce (cortico-médullaire)</span>, <span class=\"kw-imagerie\">tubulaire (néphrographique)</span>, <span class=\"kw-imagerie\">excréteur tardif</span>. <br><strong>Caractérisation <span class=\"kw-etio\">tumorale</span> :</strong> tissulaire si <span class=\"kw-imagerie\">rehaussement &gt; 15 UH</span>, sinon kystique. <strong>Critères radiologiques de malignité (tumeur solide) :</strong> <span class=\"kw-imagerie\">rehaussement &gt; 15 UH</span>, <span class=\"kw-imagerie\">caractère hétérogène</span>, <span class=\"kw-alerte\">nécrose intra-tumorale</span>, <span class=\"kw-alerte\">calcifications intra-tumorales</span>. <strong>Particularités :</strong> détection de <span class=\"kw-imagerie\">densité lipidique</span> (angiomyolipome) ; <span class=\"kw-def\">classification de Bosniak</span> si kystique. <br><strong>Extension locorégionale :</strong> <span class=\"kw-alerte\">thrombus tumoral</span> (veine rénale, VCI, OD), <span class=\"kw-bio\">envahissement</span> <span class=\"kw-clinique\">foie</span> / <span class=\"kw-clinique\">côlon</span> / <span class=\"kw-clinique\">surrénale</span>, <span class=\"kw-clinique\">adénopathies lombo-aortiques</span>, métastases <span class=\"kw-clinique\">hépatiques</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TDM thoracique</span></td>\n            <td><span class=\"kw-alerte\">Systématiquement associée à la TDM-AP</span></td>\n            <td><span class=\"kw-def\">Bilan d'extension</span> pulmonaire (1ᵉʳ site métastatique du CRCC)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">IRM rénale</span></td>\n            <td>Non systématique — situations particulières</td>\n            <td><strong>Indications :</strong> <span class=\"kw-ci\">altération de la fonction rénale</span> (<span class=\"kw-bio\">DFG</span> <span class=\"kw-chiffre\">&lt; 60 mL/min</span>) ; <br>lésions kystiques mal caractérisées par <span class=\"kw-clinique\">les</span> autres imageries ; <br>évaluation du <span class=\"kw-imagerie\">niveau supérieur d'un thrombus veineux</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Scintigraphie osseuse</span></td>\n            <td>Si point d'appel (douleur, hypercalcémie)</td>\n            <td>Bilan métastatique osseux</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TDM ou IRM cérébrale</span></td>\n            <td>Si point d'appel (signes neurologiques)</td>\n            <td>Bilan métastatique cérébral (attention : <span class=\"kw-alerte\">hémorragies parenchymateuses</span> possibles avec <span class=\"kw-clinique\">les</span> métastases de CRCC)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Stratégie diagnostique selon la présentation (tumeurs tissulaires)</h4>\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Malignité</th><th><span class=\"kw-def\">Bilan d'extension</span></th><th><span class=\"kw-bio\">Histologie</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Petite tumeur localisée &lt; 4 cm</span> (T1a)</td>\n            <td><span class=\"kw-chiffre\">80 %</span> bénin /<span class=\"kw-chiffre\"> 20 %</span> malin</td>\n            <td><span class=\"kw-imagerie\">TDM-TAP injectée</span></td>\n            <td><strong><span class=\"kw-ttt\">Exérèse</span> chirurgicale 1ʳᵉ intention</strong> (rôle diagnostique + thérapeutique) ; <br><span class=\"kw-def\">PBR</span> dans <span class=\"kw-clinique\">les</span> situations difficiles.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Tumeur localisée &gt; 4 cm</span> (T1b, T2)</td>\n            <td>Souvent malin</td>\n            <td><span class=\"kw-imagerie\">TDM-TAP injectée</span></td>\n            <td><strong><span class=\"kw-ttt\">Exérèse</span> chirurgicale 1ʳᵉ intention</strong> ; <br>PBR dans <span class=\"kw-clinique\">les</span> situations difficiles.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Tumeur localement avancée</span> (<span class=\"kw-bio\">envahissement</span> graisse péri-rénale, veine rénale, VCI, <span class=\"kw-clinique\">adénopathie</span>)</td>\n            <td>Grande majorité maligne</td>\n            <td><span class=\"kw-imagerie\">TDM-TAP injectée</span></td>\n            <td><strong>Traitement chirurgical sans preuve histologique</strong> (la <span class=\"kw-ttt\">chirurgie</span> sert à la fois de diagnostic et de traitement)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Tumeur métastatique d'emblée</span> (<span class=\"kw-clinique\">AEG</span>, <span class=\"kw-bio\">anémie</span>, <span class=\"kw-clinique\">fièvre inexpliquée</span>)</td>\n            <td>—</td>\n            <td><span class=\"kw-imagerie\">TDM-TAP injectée</span> ; <br><span class=\"kw-imagerie\">Scintigraphie osseuse</span> si point d'appel ; <br><span class=\"kw-imagerie\">TDM/IRM cérébrale</span> si point d'appel</td>\n            <td><span class=\"kw-alerte\">Preuve histologique nécessaire</span> avant traitement médical → <span class=\"kw-def\">PBR percutanée</span> généralement, parfois néphrectomie</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Stratégie diagnostique si tumeur kystique — <span class=\"kw-def\">classification</span> de Bosniak 2019</h4>\n      <p><span class=\"kw-clinique\">Les</span> tumeurs kystiques représentent <span class=\"kw-chiffre\">5-10 %</span> des tumeurs du rein, généralement <strong>peu agressives</strong>. Démarche imagerie : <span class=\"kw-imagerie\">échographie</span> (découverte, nature kystique) → <span class=\"kw-imagerie\">TDM-AP injectée</span> (référence) → <span class=\"kw-imagerie\">IRM ou écho de contraste</span> si doute.</p>\n      <table >\n        <thead>\n          <tr><th>Bosniak</th><th>Caractéristiques</th><th>Conduite à tenir</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>I</strong></td><td><span class=\"kw-imagerie\">Kyste simple</span> : paroi fine, contenu anéchogène, pas de cloison ni calcification</td><td><span class=\"kw-def\">Bénin</span> — pas de <span class=\"kw-def\">surveillance</span></td></tr>\n          <tr><td><strong>II</strong></td><td>Fines cloisons, calcifications fines, hyperdensité &lt;<span class=\"kw-chiffre\"> 3 cm</span></td><td><span class=\"kw-def\">Bénin</span> — pas de <span class=\"kw-def\">surveillance</span></td></tr>\n          <tr><td><strong>IIF</strong></td><td>Caractéristiques intermédiaires (« <em>follow-up</em> »)</td><td><span class=\"kw-alerte\">Surveillance imagerie</span> rapprochée</td></tr>\n          <tr><td><strong>III</strong></td><td>Cloisons épaisses ou irrégulières, rehaussement de paroi/cloisons</td><td><span class=\"kw-alerte\">Chirurgie indiquée</span> (malignité ~<span class=\"kw-chiffre\"> 50 %</span>)</td></tr>\n          <tr><td><strong>IV</strong></td><td>Composante solide tissulaire avec rehaussement</td><td><span class=\"kw-alerte\">Chirurgie indiquée</span> — malignité <span class=\"kw-alerte\">quasi-certaine</span></td></tr>\n        </tbody>\n      </table>\n      <p>🚩 <strong>Signes suspects d'un kyste</strong> à connaître : <span class=\"kw-imagerie\">cloisons</span>, <span class=\"kw-imagerie\">calcifications</span>, <span class=\"kw-imagerie\">végétations intrakystiques</span>, <span class=\"kw-imagerie\">épaississement des parois ou cloisons</span>, <span class=\"kw-imagerie\">rehaussement de la paroi ou des cloisons</span> après injection.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-ttt\">Biopsie</span> rénale percutanée — indications et <span class=\"kw-ci\">contre-indications</span></h4>\n      <p>La <span class=\"kw-ttt\">biopsie</span> n'est <strong>pas systématique</strong>. Modalités : anesthésie locale, voie percutanée <span class=\"kw-imagerie\">guidée par TDM ou échographie</span>, idéalement en ambulatoire. Elle est recommandée si elle peut <strong>influencer la décision thérapeutique</strong>.</p>\n      <table >\n        <thead>\n          <tr><th>Indications</th><th><span class=\"kw-ci\">Contre-indications</span> / Non recommandée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong>Doute imagerie :</strong> tumeur qui n'est pas un cancer du rein (<span class=\"kw-clinique\">sarcome</span>, <span class=\"kw-clinique\">lymphome</span>, <span class=\"kw-clinique\">métastase d'un autre primitif</span>) ; <br>\n              <strong><span class=\"kw-def\">Terrain</span> :</strong> patient âgé (<span class=\"kw-chiffre\">&gt; 70 ans</span>) avec <span class=\"kw-def\">comorbidités</span>, <span class=\"kw-clinique\">rein unique</span>, <span class=\"kw-clinique\">insuffisance rénale chronique</span>, <span class=\"kw-ttt\">exérèse</span> à risque selon la localisation ; <br>\n              <strong>Avant traitement médical</strong> d'une tumeur métastatique ; <br>\n              <strong>Avant <span class=\"kw-def\">surveillance</span> active</strong> ou <strong>traitement ablatif</strong> (<span class=\"kw-def\">radiofréquence</span>, <span class=\"kw-def\">cryothérapie</span>)\n            </td>\n            <td>\n              <span class=\"kw-ci\">Tumeur kystique sans contingent solide</span> ; <br>\n              <span class=\"kw-ci\">Angiomyolipome typique</span> ; <br>\n              <span class=\"kw-ci\">Suspicion de carcinome urothélial</span> (<span class=\"kw-alerte\">risque d'ensemencement</span> du trajet — <span class=\"kw-ci\">CI absolue</span> à connaître ++) ; <br>\n              <span class=\"kw-ci\">Risque hémorragique majeur</span> (trouble de l'hémostase, <span class=\"kw-ttt\">antiagrégants</span> non interrompus)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">🚩 <strong><span class=\"kw-alerte\">Drapeau rouge</span> à connaître.</strong> Devant une suspicion de <span class=\"kw-def\">carcinome urothélial</span> des voies excrétrices supérieures (<span class=\"kw-bio\">hématurie</span> + <span class=\"kw-clinique\">lésion</span> centrée sur <span class=\"kw-clinique\">les</span> cavités), la <span class=\"kw-alerte\">biopsie percutanée est contre-indiquée</span> en raison du <span class=\"kw-alerte\">risque d'ensemencement sur le trajet de biopsie</span> — la démarche passe alors par <span class=\"kw-imagerie\">uroscanner</span>, <span class=\"kw-imagerie\">URS-S ± biopsies endoscopiques</span> et <span class=\"kw-bio\">cytologie urinaire</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 260 — <span class=\"kw-bio\">Hématurie</span> · 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique · 292 — Diagnostic des cancers</em></p>","frequence":8},{"id":"311-6","rang":"B","rubrique":"Contenu multimédia","titre":"Echographie d'un kyste rénal simple","contenu":"<p>L'<span class=\"kw-imagerie\">échographie rénale</span> est le <strong>mode de découverte le plus fréquent</strong> d'une tumeur du rein. Elle distingue immédiatement <span class=\"kw-clinique\">les</span> lésions <span class=\"kw-def\">kystiques</span> (paroi liquidienne anéchogène) des lésions <span class=\"kw-def\">solides / tissulaires</span> (échogènes). Le <span class=\"kw-def\">kyste rénal simple</span> est très fréquent après <span class=\"kw-chiffre\">50 ans</span> — sémiologie échographique à reconnaître <strong>par cœur</strong>.</p>\n      <table >\n        <thead>\n          <tr><th>Critères du kyste simple <span class=\"kw-def\">bénin</span> (Bosniak I)</th><th>Signes suspects 🚩 (kyste atypique → Bosniak ≥ IIF)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>\n              <span class=\"kw-imagerie\">Paroi fine</span> et régulière ; <br>\n              <span class=\"kw-imagerie\">Contenu hydrique anéchogène homogène</span> ; <br>\n              <span class=\"kw-imagerie\">Renforcement postérieur échographique</span> ; <br>\n              <span class=\"kw-imagerie\">Pas de membrane interne</span> ; <br>\n              <span class=\"kw-imagerie\">Pas de septa</span> ; <br>\n              <span class=\"kw-imagerie\">Pas de bourgeon intrakystique</span> ; <br>\n              <span class=\"kw-imagerie\">Pas de calcification</span>\n            </td>\n            <td>\n              <span class=\"kw-alerte\">Cloisons</span> internes ; <br>\n              <span class=\"kw-alerte\">Calcifications</span> (fines ou épaisses) ; <br>\n              <span class=\"kw-alerte\">Végétations intrakystiques</span> ; <br>\n              <span class=\"kw-alerte\">Épaississement des parois ou des cloisons</span> ; <br>\n              <span class=\"kw-alerte\">Rehaussement de la paroi ou des cloisons</span> après injection de PDC (à explorer en <span class=\"kw-imagerie\">TDM</span> ou écho de contraste)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Devant un <strong>kyste simple typique</strong>, aucune <span class=\"kw-def\">surveillance</span> ni examen complémentaire ne sont nécessaires. Dès qu'un signe suspect apparaît, la <span class=\"kw-clinique\">lésion</span> bascule en Bosniak ≥ IIF et nécessite une <span class=\"kw-imagerie\">TDM-AP injectée 4 temps</span> ± <span class=\"kw-imagerie\">écho de contraste</span> pour reclassification (<span class=\"kw-def\">surveillance</span>, <span class=\"kw-def\">chirurgie</span>).</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/311/echo-kyste-simple.png\" alt=\"Échographie rénale droite montrant un kyste rénal simple : formation anéchogène (contenu liquidien) à paroi imperceptible, fine cloison intralésionnelle et renforcement postérieur hyperéchogène derrière la formation liquidienne\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Échographie</span> d'un kyste rénal simple (rein droit) : formation anéchogène, paroi fine imperceptible, fine cloison, renforcement postérieur — critères Bosniak I.</figcaption>\n      </figure>","frequence":1}],"astuces":[],"strategie":{"hospit":"<p><strong>Découverte :</strong> <span class=\"kw-clinique\">fortuite</span> dans <span class=\"kw-chiffre\">70-80 %</span> des cas, sur une imagerie réalisée pour une autre raison.<br><strong><span class=\"kw-ttt\">Biopsie</span> rénale (PBR) :</strong> <span class=\"kw-ttt\">voie percutanée sous anesthésie locale</span>, guidée par <span class=\"kw-imagerie\">TDM ou échographie</span>, idéalement en <span class=\"kw-ttt\">ambulatoire</span>.<br><strong>Oncogénétique :</strong> <span class=\"kw-ttt\">consultation proposée</span> si <span class=\"kw-chiffre\">âge &lt; 45 ans</span>, sous-type autre que <span class=\"kw-etio\">carcinome à cellules claires</span>, <span class=\"kw-etio\">tumeurs multiples / bilatérales</span>, <span class=\"kw-clinique\">manifestations extra-rénales</span> évocatrices ou plusieurs cas familiaux.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Triade classique de Guyon</span> (<span class=\"kw-chiffre\">&lt; 10 %</span>) : <span class=\"kw-clinique\">hématurie</span> + <span class=\"kw-clinique\">lombalgie</span> + <span class=\"kw-clinique\">masse lombaire</span> — témoigne d'une maladie localement avancée.</li><li><span class=\"kw-clinique\">Hématurie macroscopique totale</span> ou <span class=\"kw-clinique\">colique néphrétique</span> par caillotage si tumeur proche du hile.</li><li><span class=\"kw-clinique\">Varicocèle</span> : <span class=\"kw-clinique\">gauche</span> (<span class=\"kw-etio\">thrombus de la veine rénale gauche</span>), plus rarement droite (<span class=\"kw-etio\">thrombus de la VCI</span>).</li><li><span class=\"kw-alerte\">AEG</span> (<span class=\"kw-clinique\">asthénie</span>, fièvre, sueurs nocturnes, <span class=\"kw-clinique\">amaigrissement</span>) et <span class=\"kw-bio\">syndrome inflammatoire</span> — penser au cancer du rein devant une <span class=\"kw-alerte\">fièvre inexpliquée</span>.</li><li>Syndromes paranéoplasiques : <span class=\"kw-bio\">polyglobulie</span> (EPO) ou <span class=\"kw-bio\">anémie</span>, <span class=\"kw-bio\">hypercalcémie</span> (PTHrp), <span class=\"kw-clinique\">HTA</span> (rénine), <span class=\"kw-etio\">syndrome de Stauffer</span>.</li><li>Signes métastatiques : <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">douleurs osseuses</span>, <span class=\"kw-clinique\">troubles neurologiques</span>.</li><li>Imagerie d'extension : <span class=\"kw-radio\">thrombus tumoral</span> dans la veine rénale voire la <span class=\"kw-radio\">VCI</span>, <span class=\"kw-radio\">adénopathies lombo-aortiques</span>, <span class=\"kw-bio\">envahissement</span> de la <span class=\"kw-radio\">graisse péri-rénale</span> ou des organes de voisinage.</li><li>Kyste de <span class=\"kw-def\">Bosniak</span> suspect : <span class=\"kw-radio\">cloisons</span>, <span class=\"kw-radio\">calcifications</span>, <span class=\"kw-radio\">végétations intrakystiques</span>, <span class=\"kw-radio\">épaississement ou rehaussement</span> des parois/cloisons.</li></ul>","principes":"<p>Stratégie guidée par la nature (<span class=\"kw-imagerie\">solide vs kystique</span>), la <span class=\"kw-chiffre\">taille</span> et l'<span class=\"kw-alerte\">extension</span> ; la <span class=\"kw-ttt\">chirurgie</span> reste le pilier des formes localisées.</p><p><strong>Tumeur solide localisée < 4 cm</strong></p><p><span class=\"kw-ttt\">Exérèse chirurgicale</span> recommandée en 1re intention ; <span class=\"kw-ttt\">surveillance active</span> ou <span class=\"kw-ttt\">traitement ablatif</span> (radiofréquence, <span class=\"kw-ttt\">cryothérapie</span>) en option ; <span class=\"kw-ttt\">PBR</span> dans <span class=\"kw-clinique\">les</span> situations difficiles.</p><ul><li>Souvent <span class=\"kw-clinique\">asymptomatique</span>, de <span class=\"kw-clinique\">découverte fortuite</span> ; ~<span class=\"kw-chiffre\">80 %</span> malignes.</li><li>Bilan : <span class=\"kw-imagerie\">TDM-TAP injectée</span>.</li></ul><p><strong>Tumeur solide localisée <span class=\"kw-chiffre\">> 4 cm</span> (T1b–T2)</strong></p><p><span class=\"kw-ttt\">Exérèse chirurgicale</span> recommandée en 1re intention (<span class=\"kw-ttt\">PBR</span> si situation difficile).</p><ul><li>Souvent <span class=\"kw-clinique\">asymptomatique</span>, de découverte fortuite ; souvent maligne.</li><li>Bilan : <span class=\"kw-imagerie\">TDM-TAP injectée</span>.</li></ul><p><strong>Tumeur localement avancée</strong></p><p><span class=\"kw-ttt\">Traitement chirurgical sans preuve histologique</span>.</p><ul><li>Symptomatique : <span class=\"kw-clinique\">hématurie</span>, <span class=\"kw-clinique\">lombalgie</span>, <span class=\"kw-clinique\">masse lombaire</span> ; <span class=\"kw-bio\">anémie</span> possible.</li><li>Imagerie : <span class=\"kw-bio\">envahissement</span> <span class=\"kw-radio\">graisse péri-rénale</span>, <span class=\"kw-radio\">veine rénale</span>, <span class=\"kw-radio\">VCI</span> ; <span class=\"kw-radio\">adénopathie lombo-aortique</span>.</li><li>Hypervascularisation anarchique → <span class=\"kw-alerte\">risque hémorragique</span> peropératoire (peut justifier une <span class=\"kw-ttt\">embolisation pré-opératoire</span>).</li></ul><p><strong>Tumeur métastatique</strong></p><p><span class=\"kw-ttt\">Preuve histologique</span> (PBR) indispensable avant le <span class=\"kw-ttt\">traitement médical</span>.</p><ul><li><span class=\"kw-alerte\">AEG</span>, <span class=\"kw-bio\">anémie</span>, parfois <span class=\"kw-clinique\">fièvre</span>.</li><li>Sites : <span class=\"kw-etio\">poumon</span>, <span class=\"kw-etio\">foie</span>, <span class=\"kw-etio\">os</span>, <span class=\"kw-etio\">surrénales</span>, <span class=\"kw-etio\">cerveau</span>.</li><li>Bilan : <span class=\"kw-imagerie\">TDM-TAP injectée</span>, <span class=\"kw-imagerie\">scintigraphie osseuse</span> et <span class=\"kw-imagerie\">TDM/IRM cérébrale</span> si point d'appel.</li></ul><p><strong>Tumeur kystique (<span class=\"kw-def\">classification</span> de Bosniak)</strong></p><p>Kyste simple : <span class=\"kw-ttt\">pas de traitement</span> ; kyste suspect : <span class=\"kw-imagerie\">IRM / échographie de contraste</span> puis prise en charge comme une <span class=\"kw-etio\">tumeur du rein</span>.</p><ul><li>Représentent <span class=\"kw-chiffre\">5-10 %</span> des tumeurs du rein, généralement peu agressives.</li><li>Kyste simple = <span class=\"kw-def\">bénin</span> : <span class=\"kw-radio\">paroi fine</span>, contenu <span class=\"kw-radio\">anéchogène homogène</span>, <span class=\"kw-radio\">renforcement postérieur</span>, pas de septa.</li><li>Kyste suspect : <span class=\"kw-radio\">cloisons</span>, <span class=\"kw-radio\">calcifications</span>, <span class=\"kw-radio\">végétations</span>, <span class=\"kw-radio\">rehaussement</span> des parois/cloisons.</li></ul><p><strong>Angiomyolipome</strong></p><p><span class=\"kw-ttt\">Traitement préventif</span> si <span class=\"kw-chiffre\">taille &gt; 4 cm</span>.</p><ul><li>Tumeur <span class=\"kw-def\">bénigne</span> associant 3 composantes (vasculaire, musculaire, <span class=\"kw-def\">adipeuse</span>) ; <span class=\"kw-radio\">plage graisseuse</span> à l'imagerie.</li><li>Peut s'intégrer dans la <span class=\"kw-etio\">sclérose tubéreuse de Bourneville</span> ; <span class=\"kw-alerte\">risque de saignement</span>.</li></ul><p><strong><span class=\"kw-ttt\">Biopsie</span> rénale (PBR) — indications / limites</strong></p><ul><li>Indiquée si elle peut <span class=\"kw-ttt\">modifier la décision</span> : doute diagnostique (<span class=\"kw-etio\">sarcome</span>, <span class=\"kw-etio\">lymphome</span>, <span class=\"kw-etio\">métastase</span>), sujet <span class=\"kw-chiffre\">&gt; 70 ans</span> avec <span class=\"kw-def\">comorbidités</span>, rein unique, <span class=\"kw-etio\">IRC</span>, avant traitement médical d'une tumeur métastatique, avant <span class=\"kw-def\">surveillance</span> active / traitement ablatif.</li><li><span class=\"kw-ci\">Non recommandée</span> si : tumeur kystique sans contingent solide, angiomyolipome typique, <span class=\"kw-ci\">suspicion de carcinome urothélial</span> (risque d'ensemencement), <span class=\"kw-ci\">risque hémorragique majeur</span>.</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Surveillance</span> active :</strong> option pour <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">petites tumeurs</span> du sujet âgé / à <span class=\"kw-def\">comorbidités</span>, après <span class=\"kw-ttt\">PBR</span>.<br><strong>Après néphrectomie :</strong> surveillance prolongée car <span class=\"kw-chiffre\">10-30 %</span> des stades localisés deviendront <span class=\"kw-alerte\">métastatiques</span>.<br><strong>Particularité :</strong> le cancer du rein peut <span class=\"kw-alerte\">métastaser dans n'importe quel organe, même plusieurs années après</span> le diagnostic.</p>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-17-item-311-tumeurs-du-rein-de-ladulte/","label":"AFU — Chapitre 17 item 311 tumeurs du rein de ladulte"},{"href":"https://www.arcagy.org/infocancer/localisations/rein-et-voies-urinaires/cancer-rein/formes-de-la-maladie/les-differents-stades.html/","label":"Les differents stades"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"<span class=\"kw-clinique\">Masse</span> rénale (<span class=\"kw-imagerie\">échographie</span>) : solide ou kystique ? — <span class=\"kw-clinique\">Découverte fortuite</span> dans <span class=\"kw-chiffre\">70-80 %</span> des cas ; <span class=\"kw-imagerie\">échographie</span> complétée systématiquement par <span class=\"kw-imagerie\">TDM-AP injectée</span>","detail":"<h4>CAT — Tumeur du rein découverte à l'imagerie — Nature solide <span class=\"kw-bio\">vs</span> kystique, puis stratification selon taille et extension</h4>","branches":[{"to":"q-meta","label":"Solide / tissulaire","color":"blue"},{"to":"q-bosniak","label":"Kystique (5-10 %)","color":"blue"}]},{"id":"q-meta","kind":"decision","label":"Signes de maladie métastatique ou d'extension ? — <span class=\"kw-clinique\">AEG</span>, <span class=\"kw-bio\">anémie</span>, <span class=\"kw-clinique\">fièvre</span> ; <span class=\"kw-radio\">rehaussement &gt; 15 UH</span> confirme la nature tissulaire","branches":[{"to":"t-meta","label":"Oui — métastases / extension","color":"red"},{"to":"q-taille","label":"Non — localisée","color":"green"}]},{"id":"t-meta","kind":"terminal","label":"Tumeur métastatique — histologie puis traitement médical","color":"red","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">TDM-TAP injectée</span></li><li><span class=\"kw-imagerie\">Scintigraphie osseuse</span> si point d'appel</li><li><span class=\"kw-imagerie\">TDM / IRM cérébrale</span> si point d'appel</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">LDH</span>, bilan d'hémostase, protidémie / albuminémie</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Preuve histologique</span> (PBR) indispensable avant le <span class=\"kw-ttt\">traitement médical</span></li><li>Sites : <span class=\"kw-etio\">poumon, foie, os, surrénales, cerveau</span></li></ul>"},{"id":"q-taille","kind":"decision","label":"Taille et extension locale (<span class=\"kw-imagerie\">TDM</span>-TAP) ? — Tumeur localisée, le plus souvent <span class=\"kw-clinique\">asymptomatique</span>","branches":[{"to":"t-petite","label":"&lt; 4 cm","color":"green"},{"to":"t-grosse","label":"&gt; 4 cm (T1b–T2)","color":"amber"},{"to":"t-avancee","label":"Localement avancée","color":"red"}]},{"id":"t-petite","kind":"terminal","label":"<span class=\"kw-ttt\">Exérèse</span> chirurgicale en 1re intention — Localisée <span class=\"kw-chiffre\">&lt; 4 cm</span> (~<span class=\"kw-chiffre\">80 %</span> malignes)","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Exérèse chirurgicale</span> recommandée en 1re intention</li><li><span class=\"kw-ttt\">Surveillance active</span> ou <span class=\"kw-ttt\">traitement ablatif</span> (radiofréquence, <span class=\"kw-ttt\">cryothérapie</span>) en option</li><li><span class=\"kw-ttt\">PBR</span> dans <span class=\"kw-clinique\">les</span> situations difficiles</li></ul>"},{"id":"t-grosse","kind":"terminal","label":"<span class=\"kw-ttt\">Exérèse</span> chirurgicale en 1re intention — Localisée <span class=\"kw-chiffre\">&gt; 4 cm</span> (T1b–T2)","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Exérèse chirurgicale</span> recommandée en 1re intention</li><li><span class=\"kw-ttt\">PBR</span> dans <span class=\"kw-clinique\">les</span> situations difficiles</li></ul>"},{"id":"t-avancee","kind":"terminal","label":"Traitement chirurgical sans preuve histologique — Tumeur localement avancée","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Hématurie</span>, <span class=\"kw-clinique\">lombalgie</span>, <span class=\"kw-clinique\">masse lombaire</span></li><li><span class=\"kw-bio\">Anémie</span> possible</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-bio\">Envahissement</span> <span class=\"kw-radio\">graisse péri-rénale</span>, <span class=\"kw-radio\">veine rénale</span>, <span class=\"kw-radio\">VCI</span></li><li><span class=\"kw-radio\">Adénopathie lombo-aortique</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Traitement chirurgical sans preuve histologique</span></li><li>Hypervascularisation anarchique → <span class=\"kw-ttt\">embolisation pré-opératoire</span> possible (<span class=\"kw-alerte\">risque hémorragique</span>)</li></ul>"},{"id":"q-bosniak","kind":"decision","label":"<span class=\"kw-def\">Classification</span> de Bosniak : signes suspects ? — <span class=\"kw-imagerie\">TDM-AP injectée</span> = référence ; <span class=\"kw-imagerie\">IRM</span> ou <span class=\"kw-imagerie\">échographie de contraste</span> si mal caractérisé","branches":[{"to":"t-kyste-simple","label":"Non — kyste simple","color":"green"},{"to":"t-kyste-suspect","label":"Oui — signes suspects","color":"amber"}]},{"id":"t-kyste-simple","kind":"terminal","label":"Kyste simple bénin — pas de traitement — Très fréquent après <span class=\"kw-chiffre\">50 ans</span>","color":"green","detail":"<h4>Imagerie</h4><ul><li><span class=\"kw-radio\">Paroi fine</span>, contenu <span class=\"kw-radio\">anéchogène homogène</span>, <span class=\"kw-radio\">renforcement postérieur</span></li><li>Pas de membrane, pas de septa, pas de bourgeon</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-clinique\">Lésion</span> <span class=\"kw-def\">bénigne</span> — pas de traitement spécifique</li></ul>"},{"id":"t-kyste-suspect","kind":"terminal","label":"Kyste suspect → prise en charge tumorale — Kyste atypique de Bosniak élevé","color":"amber","detail":"<h4>Imagerie</h4><ul><li><span class=\"kw-radio\">Cloisons</span>, <span class=\"kw-radio\">calcifications</span>, <span class=\"kw-radio\">végétations intrakystiques</span></li><li><span class=\"kw-radio\">Épaississement / rehaussement</span> des parois ou cloisons</li></ul><h4>Conduite</h4><ul><li>Caractérisation par <span class=\"kw-imagerie\">IRM</span> ou <span class=\"kw-imagerie\">échographie de contraste</span></li><li>Prise en charge comme une <span class=\"kw-etio\">tumeur du rein</span></li></ul>"}]},"cards":[{"i":"0b567f39e439","n":311,"o":"311-4","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du rein","q":"Comment un varicocèle peut-il être une manifestation d'une tumeur du rein ?","a":"<p>Un varicocèle, le plus souvent <strong>gauche</strong>, peut être le signe d'une extension veineuse par un <strong>thrombus de la veine rénale gauche</strong>. Plus rarement, un varicocèle droit peut être dû à un thrombus de la <strong>veine cave inférieure</strong>.</p>"},{"i":"443aa0593c61","n":311,"o":"311-4","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du rein","q":"Quels sont les principaux syndromes paranéoplasiques associés aux tumeurs du rein et leurs mécanismes ?","a":"<p>Les principaux syndromes paranéoplasiques sont :</p><ul><li><strong>Polyglobulie</strong> : par hypersécrétion d'<strong>EPO</strong> par la tumeur.</li><li><strong>Anémie</strong> : par inflammation chronique ou saignement chronique.</li><li><strong>Hypercalcémie</strong> : par hypersécrétion de <strong>PTHrp</strong>.</li><li><strong>HTA</strong> : par hypersécrétion de <strong>rénine</strong>.</li><li><strong>AEG</strong> (altération de l'état général) : asthénie, fièvre, sueurs nocturnes, amaigrissement.</li><li><strong>Syndrome de Stauffer</strong> : hépatomégalie douloureuse et anomalies biologiques hépatiques, <strong>sans métastase hépatique</strong> (piège classique à ne pas confondre avec une métastase).</li></ul>"},{"i":"cc31868f80c1","n":311,"o":"311-4","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du rein","q":"Quelle est la présentation clinique la plus fréquente des tumeurs du rein de l'adulte ?","a":"<p>La présentation clinique la plus fréquente est la <strong>découverte fortuite</strong> (<strong>70-80 %</strong> des cas) lors d'une imagerie réalisée pour un autre motif. Ces tumeurs sont alors souvent à un stade asymptomatique et ont un meilleur pronostic.</p>"},{"i":"d36f0afad10f","n":311,"o":"311-4","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du rein","q":"Quelle est la différence sémiologique entre un ébranlement lombaire et un contact lombaire ?","a":"<p>L'<strong>ébranlement lombaire</strong> est positif dans les coliques néphrétiques ou les pyélonéphrites aiguës (PNA). Le <strong>contact lombaire</strong> est positif dans les tumeurs rénales, les polykystoses rénales (PKRAD) ou des reins de grande taille, et correspond à la perception d'une masse lors de la palpation bimanuelle. C'est un piège sémiologique classique.</p>"},{"i":"d741f4e9978d","n":311,"o":"311-4","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du rein","q":"Quels sont les signes cliniques de la triade de Guyon et que signifie sa présence dans le cadre d'une tumeur du rein ?","a":"<p>La triade de Guyon se compose de :</p><ul><li><strong>Hématurie</strong></li><li><strong>Lombalgie</strong></li><li><strong>Masse lombaire</strong></li></ul><p>Elle est présente dans moins de <strong>10 %</strong> des cas et signe une <strong>maladie localement avancée</strong>, ce n'est pas un signe précoce.</p>"},{"i":"27b89b3f9bac","n":311,"o":"311-5","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires nécessaires en cas suspicion clinique de tumeur du rein","q":"Quelles sont les indications et les contre-indications de la biopsie rénale percutanée dans la prise en charge d'une tumeur du rein ?","a":"<p>La biopsie rénale percutanée n'est pas systématique et est recommandée si elle peut influencer la décision thérapeutique.</p><ul><li><p><strong>Indications</strong> :</p><ul><li>Doute imagerie (sarcome, lymphome, métastase d'un autre primitif).</li><li>Terrain particulier (patient âgé > <strong>70 ans</strong>, rein unique, insuffisance rénale chronique).</li><li>Avant traitement médical d'une tumeur métastatique.</li><li>Avant surveillance active ou traitement ablatif (radiofréquence, cryothérapie).</li></ul></li><li><p><strong>Contre-indications / Non recommandée</strong> :</p><ul><li>Tumeur kystique sans contingent solide.</li><li>Angiomyolipome typique.</li><li>Suspicion de <strong>carcinome urothélial</strong> (risque d'ensemencement ++).</li><li>Risque hémorragique majeur (trouble de l'hémostase, antiagrégants non interrompus).</li></ul></li></ul>"},{"i":"6a14ba9b75f4","n":311,"o":"311-5","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires nécessaires en cas suspicion clinique de tumeur du rein","q":"Quelle est la hiérarchie des examens d'imagerie recommandés en cas de suspicion clinique de tumeur du rein ?","a":"<p>La démarche d'imagerie est hiérarchisée :</p><ul><li><p><strong>Échographie rénale</strong> en 1<sup>re</sup> intention.</p></li><li><p><strong>TDM abdominale et pelvienne injectée 4 temps</strong> en 2<sup>e</sup> intention systématique.</p></li><li><p><strong>TDM thoracique</strong> systématiquement associée à la TDM-AP.</p></li><li><p><strong>IRM rénale</strong> si besoin (non systématique).</p></li><li><p><strong>Bilan métastatique complémentaire</strong> (scintigraphie osseuse, TDM/IRM cérébrale) si points d'appel.</p></li></ul>"},{"i":"bfd033043654","n":311,"o":"311-5","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires nécessaires en cas suspicion clinique de tumeur du rein","q":"Quel est l'examen de référence pour la caractérisation et l'extension d'une tumeur rénale et quelles sont ses particularités ?","a":"<p>L'examen de référence est la <strong>TDM abdominale et pelvienne injectée 4 temps</strong>. Elle permet :</p><ul><li><p><strong>Caractérisation tumorale</strong> : tissulaire si rehaussement > <strong>15 UH</strong>, sinon kystique.</p></li><li><p><strong>Critères radiologiques de malignité</strong> (tumeur solide) : rehaussement > <strong>15 UH</strong>, caractère hétérogène, nécrose intra-tumorale, calcifications intra-tumorales.</p></li><li><p>Détection de densité lipidique pour les angiomyolipomes.</p></li><li><p>Classification de <strong>Bosniak</strong> si kystique.</p></li><li><p><strong>Extension locorégionale</strong> : thrombus tumoral (veine rénale, VCI), envahissement d'organes de voisinage, adénopathies.</p></li></ul>"},{"i":"d39ecf0c4655","n":311,"o":"311-5","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires nécessaires en cas suspicion clinique de tumeur du rein","q":"Quand réalise-t-on une IRM rénale dans le bilan d'une tumeur du rein ?","a":"<p>L'IRM rénale n'est pas systématique, mais elle est indiquée dans des situations particulières :</p><ul><li>Altération de la <strong>fonction rénale</strong> (DFG < <strong>60 mL/min</strong>).</li><li>Lésions kystiques mal caractérisées par les autres imageries.</li><li>Évaluation du niveau supérieur d'un <strong>thrombus veineux</strong>.</li></ul>"},{"i":"e322e4fce486","n":311,"o":"311-5","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires nécessaires en cas suspicion clinique de tumeur du rein","q":"Quelle est la stratégie diagnostique basée sur l'histologie pour une petite tumeur rénale localisée de moins de 4 cm (T1a) ?","a":"<p>Pour une petite tumeur rénale localisée < <strong>4 cm</strong> (T1a), la stratégie est :</p><ul><li>Bilan d'extension par <strong>TDM-TAP injectée</strong>.</li><li>L'<strong>exérèse chirurgicale</strong> est généralement la 1<sup>re</sup> intention, ayant un rôle à la fois diagnostique et thérapeutique.</li><li>La biopsie percutanée (PBR) peut être envisagée dans les situations difficiles ou pour des indications spécifiques si elle impacte la décision thérapeutique.</li></ul>"}]};